INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5191381, 755196, 96751, '<td valign="top">Nice idea.  The model''s position could have been more forward-leaning (into the wind), and the lighting just a bit crisper.</td>', 'Nice idea.  The model''s position could have been more forward-leaning (into the wind), and the lighting just a bit crisper.', '2009-01-14 16:54:41.000000', NULL, 1),
(5191382, 755959, 96751, '<td valign="top">Strong image.  I can definitely see this as a logo.  Especially if the lunch box was more identifiable as such.</td>', 'Strong image.  I can definitely see this as a logo.  Especially if the lunch box was more identifiable as such.', '2009-01-14 16:55:22.000000', NULL, 1),
(5191384, 755543, 96751, '<td valign="top">Nice.  Great attitude on the guy, nice composition (even if the cord bugs me).  Lighting on the face is too harsh, creating unattractive shadows.</td>', 'Nice.  Great attitude on the guy, nice composition (even if the cord bugs me).  Lighting on the face is too harsh, creating unattractive shadows.', '2009-01-14 16:56:13.000000', NULL, 1),
(5191389, 755944, 96751, '<td valign="top">Boys and their toys.    Great idea, although the face is underlit.  The legs reflected on the ground are also distracting.</td>', 'Boys and their toys.    Great idea, although the face is underlit.  The legs reflected on the ground are also distracting.', '2009-01-14 16:57:30.000000', NULL, 1),
(5191390, 755972, 96751, '<td valign="top">The foreground is just too prominent to make this an effective "see through" shot.</td>', 'The foreground is just too prominent to make this an effective "see through" shot.', '2009-01-14 16:58:05.000000', NULL, 1),
(5191391, 753945, 96751, '<td valign="top">Maybe a stock TRAVEL shot...</td>', 'Maybe a stock TRAVEL shot...', '2009-01-14 16:58:26.000000', NULL, 1),
(5191393, 755840, 96751, '<td valign="top">A bit too dark for stock.  Key lighting on the face is good, if harsh, but hands with phone should also have been lit.  There is also too much background for my taste; a tighter crop without the bright spot on the left would have made the composition stronger.</td>', 'A bit too dark for stock.  Key lighting on the face is good, if harsh, but hands with phone should also have been lit.  There is also too much background for my taste; a tighter crop without the bright spot on the left would have made the composition stronger.', '2009-01-14 16:59:46.000000', NULL, 1),
(5191395, 755526, 96751, '<td valign="top">Nice stock subject; lighting is a bit flat, especially on the face.</td>', 'Nice stock subject; lighting is a bit flat, especially on the face.', '2009-01-14 17:00:24.000000', NULL, 1),
(5191397, 755084, 96751, '<td valign="top">I love this shot.  The textures, the subject, the treatment, the attitude.  Don''t know if it would qualify as "stock" though.</td>', 'I love this shot.  The textures, the subject, the treatment, the attitude.  Don''t know if it would qualify as "stock" though.', '2009-01-14 17:01:00.000000', NULL, 1),
(5191398, 755606, 96751, '<td valign="top">I love this shot.  Except for the lighting on the face which I find a bit harsh and underlit, there is great movement, attitude, composition.  Nice job.</td>', 'I love this shot.  Except for the lighting on the face which I find a bit harsh and underlit, there is great movement, attitude, composition.  Nice job.', '2009-01-14 17:01:50.000000', NULL, 1),
(5191401, 755136, 96751, '<td valign="top">Nice lines, bold shapes, great colors.  I know that the window frame also "frames" the shot, but the chair on the right is distracting.</td>', 'Nice lines, bold shapes, great colors.  I know that the window frame also "frames" the shot, but the chair on the right is distracting.', '2009-01-14 17:03:25.000000', NULL, 1),
(5191434, 755036, 31535, '<td valign="top">I like this shot, although it looks like you boosted the magenta saturation for the tie and it carried over to the face and hand. This was an advanced editing challenge so you could have fixed that.</td>', 'I like this shot, although it looks like you boosted the magenta saturation for the tie and it carried over to the face and hand. This was an advanced editing challenge so you could have fixed that.', '2009-01-14 17:28:44.000000', NULL, 1),
(5191436, 755984, 31535, '<td valign="top">lol, too funny</td>', 'lol, too funny', '2009-01-14 17:29:42.000000', NULL, 1),
(5191455, 755566, 77192, '<td valign="top">lol it made me laugh! I''m scoring you high for creativity rather than it''s value as a stock photo.</td>', 'lol it made me laugh! I''m scoring you high for creativity rather than it''s value as a stock photo.', '2009-01-14 17:41:46.000000', NULL, 1),
(5191457, 755984, 37444, '<td valign="top">Ok, this gets a 10 from me!  LOL<br/>Fantastic job! What a great and handsome model!</td>', 'Ok, this gets a 10 from me!  LOLFantastic job! What a great and handsome model!', '2009-01-14 17:43:52.000000', NULL, 1),
(5191458, 755136, 37444, '<td valign="top">At first I thought the other chair was distracting, but now I see is as balancing the image - nice job. 8</td>', 'At first I thought the other chair was distracting, but now I see is as balancing the image - nice job. 8', '2009-01-14 17:44:29.000000', NULL, 1),
