(5191704, 755984, 100773, '<td valign="top">I loved this shot. Was thinking the same idea with my dog, but I changed my mind. Glad I did! Your shot is much better than what I could dream of at the moment.</td>', 'I loved this shot. Was thinking the same idea with my dog, but I changed my mind. Glad I did! Your shot is much better than what I could dream of at the moment.', '2009-01-14 19:31:14.000000', NULL, 1),
(5191709, 755908, 100773, '<td valign="top">I find those bars, or whatever it is, a bit disturbing. I think the shot would''ve been better if they had been "smoothed out" a bit to get more attention to your motive.</td>', 'I find those bars, or whatever it is, a bit disturbing. I think the shot would''ve been better if they had been "smoothed out" a bit to get more attention to your motive.', '2009-01-14 19:34:35.000000', NULL, 1),
