(5197272, 755944, 83313, '<td valign="top">How many of those have you taken orders for since this challenge began?</td>', 'How many of those have you taken orders for since this challenge began?', '2009-01-16 21:08:15.000000', NULL, 1),
(5197291, 755972, 83313, '<td valign="top">Good, but for one thing. He looks apathetic, which doesn''t work for a stock photo. However, he''s probably been up all night getting the new systems ready to go and now you want to take his picture.</td>', 'Good, but for one thing. He looks apathetic, which doesn''t work for a stock photo. However, he''s probably been up all night getting the new systems ready to go and now you want to take his picture.', '2009-01-16 21:12:05.000000', NULL, 1),
(5197296, 755981, 83313, '<td valign="top">Pretty good, I can see this used as stock. My only nitpick is it looks like he is sweating. Maybe some tough negotiations going on here.</td>', 'Pretty good, I can see this used as stock. My only nitpick is it looks like he is sweating. Maybe some tough negotiations going on here.', '2009-01-16 21:13:44.000000', NULL, 1),
(5197301, 755599, 83313, '<td valign="top">I used to have a boss that would disappear every time the colonial was going on. He would call to check in several times a day, but would not tell us where he was. As if we didn''t know.</td>', 'I used to have a boss that would disappear every time the colonial was going on. He would call to check in several times a day, but would not tell us where he was. As if we didn''t know.', '2009-01-16 21:17:15.000000', NULL, 1),
(5197313, 755948, 83313, '<td valign="top">When I first saw this, I thought he was reading a Dave <b>Barry</b> book! Love the sticky notes. Probably could use some better lighting on this. However, you composed it well, my eye goes up to the book, and then past it to the man''s face.</td>', 'When I first saw this, I thought he was reading a Dave Barry book! Love the sticky notes. Probably could use some better lighting on this. However, you composed it well, my eye goes up to the book, and then past it to the man''s face.', '2009-01-16 21:20:41.000000', NULL, 1),
(5197323, 755984, 83313, '<td valign="top">He might apply for a position as an advertising mascot. There''s this lizard that''s really starting to annoy me and he could use a more endearing replacement.</td>', 'He might apply for a position as an advertising mascot. There''s this lizard that''s really starting to annoy me and he could use a more endearing replacement.', '2009-01-16 21:23:13.000000', NULL, 1),
