INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5201936, 755974, 62187, '<td valign="top">Great idea: 8</td>', 'Great idea: 8', '2009-01-18 13:49:18.000000', NULL, 1),
(5201937, 755948, 10858, '<td valign="top">It really looks like a sudden push of the exposure button. Next time, please, take more care of the background, it''s really distracting. Also, try to avoid flash: this is why your foregound is overexposed and the background underexposed. The aura around the book is also distracting, I guess, it is the artifact of the post-process. Next time, please, pay more attention to the set-up. Setting up the photo and the environment takes most of the time when making a photo for the challenge, but I can say, surely, it will pay off. (2)</td>', 'It really looks like a sudden push of the exposure button. Next time, please, take more care of the background, it''s really distracting. Also, try to avoid flash: this is why your foregound is overexposed and the background underexposed. The aura around the book is also distracting, I guess, it is the artifact of the post-process. Next time, please, pay more attention to the set-up. Setting up the photo and the environment takes most of the time when making a photo for the challenge, but I can say, surely, it will pay off. (2)', '2009-01-18 13:49:26.000000', NULL, 1),
(5201940, 755959, 62187, '<td valign="top">These types of photos have always done well.</td>', 'These types of photos have always done well.', '2009-01-18 13:50:04.000000', NULL, 1),
(5201943, 755136, 62187, '<td valign="top">I like it. I don''t think it''s exactly what the challenge called for but I still like it: 8</td>', 'I like it. I don''t think it''s exactly what the challenge called for but I still like it: 8', '2009-01-18 13:50:36.000000', NULL, 1),
(5201948, 756000, 62187, '<td valign="top">Wow, your edit really says ''Brochure'': all the way! 8</td>', 'Wow, your edit really says ''Brochure'': all the way! 8', '2009-01-18 13:51:17.000000', NULL, 1),
(5201954, 755847, 10858, '<td valign="top">Sorry to say that, but I really can''t see much of a conception in your composition. Let''s get closer to your subject! Get rid of the distracting elements with a good crop and focus more on the main subject which is the lady in front of the computer. A good stoch photo has very few things on it, and all those things support the main story. Try to find the best angle which describes the story what you want to tell us and you will reach a much better result next time. Try many viewpoints, later on, you can choose from more. (2)</td>', 'Sorry to say that, but I really can''t see much of a conception in your composition. Let''s get closer to your subject! Get rid of the distracting elements with a good crop and focus more on the main subject which is the lady in front of the computer. A good stoch photo has very few things on it, and all those things support the main story. Try to find the best angle which describes the story what you want to tell us and you will reach a much better result next time. Try many viewpoints, later on, you can choose from more. (2)', '2009-01-18 13:53:41.000000', NULL, 1),
(5201955, 755569, 62187, '<td valign="top">I''m not brave enough to pose myself for this shot and I doubt I know anybody that would model it for me. Plus, I don''t think I''d even think of doing something like this. However, it''s classic! The stories on your ''Business'' paper are too funny and what a coincidence! I doubt it''s exactly what they were looking for butt...? I''ll still go with an 8</td>', 'I''m not brave enough to pose myself for this shot and I doubt I know anybody that would model it for me. Plus, I don''t think I''d even think of doing something like this. However, it''s classic! The stories on your ''Business'' paper are too funny and what a coincidence! I doubt it''s exactly what they were looking for butt...? I''ll still go with an 8', '2009-01-18 13:54:13.000000', NULL, 1),
(5201957, 755908, 62187, '<td valign="top">I could see this as an advertisement in a magazine: 8</td>', 'I could see this as an advertisement in a magazine: 8', '2009-01-18 13:54:39.000000', NULL, 1),
(5201959, 754614, 62187, '<td valign="top">I don''t think this is exactly what the challenge was calling for. Like my entry is - NOT! But, it''s very funny and creative and the focus is perfect.</td>', 'I don''t think this is exactly what the challenge was calling for. Like my entry is - NOT! But, it''s very funny and creative and the focus is perfect.', '2009-01-18 13:55:46.000000', NULL, 1),
(5201960, 755566, 62187, '<td valign="top">Enter your comment here, and then cast your vote...Ok, I''ll do that...</td>', 'Enter your comment here, and then cast your vote...Ok, I''ll do that...', '2009-01-18 13:56:27.000000', NULL, 1),
(5201962, 755624, 10858, '<td valign="top">I like the concept, put not the quality of the photo. It''s always better to deal with 640 px on the longer dimension, it makes your photo more enjoyable. I am not happy with the lighting, the tones are not really nice and a lot of texture is lost. I like though, the composition. Just an idea, it would add a lot to your photo to include the subject of business or the environment into the background. A blurred cityscape with sky-screapers, or some computers as the product, anything. It would make your photo live! (3)</td>', 'I like the concept, put not the quality of the photo. It''s always better to deal with 640 px on the longer dimension, it makes your photo more enjoyable. I am not happy with the lighting, the tones are not really nice and a lot of texture is lost. I like though, the composition. Just an idea, it would add a lot to your photo to include the subject of business or the environment into the background. A blurred cityscape with sky-screapers, or some computers as the product, anything. It would make your photo live! (3)', '2009-01-18 13:57:48.000000', NULL, 1),
